using System.Net.Mail;using Forjix.Application.Abstractions.Identity;using Forjix.Application.Abstractions.Settings;using Forjix.Application.Common;namespace Forjix.Application.Features.Settings;internal sealed class SettingsService(ISettingsStore store,IFileStorage files,ICurrentUser current,TimeProvider clock):ISettingsService{public async Task<TenantSettingsView>GetAsync(CancellationToken ct=default)=>await store.GetAsync(Tenant(),ct)??throw new ResourceNotFoundException("Empresa não encontrada.");public async Task<TenantSettingsView>UpdateAsync(UpdateTenantSettingsRequest r,CancellationToken ct=default){var name=r.TradeName?.Trim();if(string.IsNullOrWhiteSpace(name)||name.Length>160)throw new RequestValidationException("Nome fantasia inválido.");var cnpj=Digits(r.Cnpj);if(cnpj is not null&&cnpj.Length!=14)throw new RequestValidationException("CNPJ deve possuir 14 dígitos.");var email=Clean(r.Email);if(email is not null)try{_=new MailAddress(email);}catch(FormatException){throw new RequestValidationException("E-mail inválido.");}if(r.Currency is not "BRL")throw new RequestValidationException("A V1 utiliza moeda BRL.");if(string.IsNullOrWhiteSpace(r.TimeZone)||r.TimeZone.Length>80)throw new RequestValidationException("Fuso horário inválido.");return await store.UpdateAsync(Tenant(),User(),r with{TradeName=name,Cnpj=cnpj,Email=email},current.CorrelationId,current.IpAddress,clock.GetUtcNow(),ct);}public async Task UploadLogoAsync(Stream stream,string contentType,string extension,CancellationToken ct=default){if(contentType is not("image/png" or "image/jpeg" or "image/webp"))throw new RequestValidationException("Use PNG, JPEG ou WebP.");var tenant=Tenant();var key=await files.SaveAsync(tenant,stream,contentType,extension,ct);await store.SetLogoKeyAsync(tenant,User(),key,current.CorrelationId,current.IpAddress,clock.GetUtcNow(),ct);}public async Task<StoredFile?>GetLogoAsync(CancellationToken ct=default){var key=await store.GetLogoKeyAsync(Tenant(),ct);return key is null?null:await files.OpenAsync(key,ct);}private Guid Tenant()=>current.TenantId??throw new ResourceNotFoundException("Tenant não encontrado.");private Guid User()=>current.UserId??throw new ResourceNotFoundException("Usuário não encontrado.");private static string?Clean(string?x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();private static string?Digits(string?x){var c=Clean(x);return c is null?null:new string(c.Where(char.IsDigit).ToArray());}}
